    return False

def cantor_numbering(N: int) -> str:
    d = 1
    total = 1
    while total < N:
        d += 1
        total += d
    prev_total = total - d
    offset = N - prev_total - 1
    if d % 2 == 1:
        a = d - offset
    else:
        a = offset + 1
    b = d + 1 - a
    return f"{a}/{b}"}

