def polynomial_to_string(n: int, coeffs) -> str:
    """
    Convert polynomial coefficients into a formatted string representation.

    :param n: Highest degree of the polynomial.
    :param coeffs: List of coefficients from highest degree to constant term.
    :return: String representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign and magnitude
        sign = '' if terms == [] and coeff > 0 else ('-' if coeff < 0 else '+')
        magnitude = abs(coeff)

        # Determine variable part based on degree
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"
        else:
            var_part = ""

        # Determine coefficient part
        if magnitude == 1 and degree >= 1:
            coeff_part = ""
        else:
            coeff_part = str(magnitude)

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)

    if not terms:
        return "0"
    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters
    ----------
    encoded : str
        A string representing the encoded information.
    original : str
        A string representing the original information corresponding to the encoded string.
    message : str
        A string representing the encrypted message to be decoded.

    Returns
    -------
    str
        The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

    # Ensure that all 26 uppercase letters are present in the mapping
    if len(mapping) < 26:
        return "Failed"

    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])

    return "".join(decoded)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """Counts pairs (P, Q) such that gcd(P, Q)=x0 and lcm(P, Q)=y0."""
    if x0 == 0 or y0 % x0 != 0:
        return 0
    m = y0 // x0

    # Euclidean algorithm for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= m:
        if m % i == 0:
            a = i
            b = m // i
            if _gcd(a, b) == 1:
                count += 1 if a == b else 2
        i += 1
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.
    """
    def build_pre(in_in: str, post_in: str) -> str:
        if not in_in:
            return ''
        root = post_in[-1]
        idx = in_in.index(root)
        left_inorder = in_in[:idx]
        right_inorder = in_in[idx+1:]
        left_postorder = post_in[:len(left_inorder)]
        right_postorder = post_in[len(left_inorder):-1]
        return root + build_pre(left_inorder, left_postorder) + build_pre(right_inorder, right_postorder)

    return build_pre(inorder, postorder)

def generate_numbers(n, rules) -> int:
    """Generate all unique numbers obtainable from n by applying the given digit‑replacement rules."""
    # Build mapping from source digit to list of target digits (as strings)
    mapping = {}
    for x, y in rules:
        mapping.setdefault(str(x), []).append(str(y))

    visited = set([n])
    queue = [n]

    while queue:
        current = queue.pop(0)
        s = str(current)
        for i, ch in enumerate(s):
            if ch in mapping:
                for new_digit in mapping[ch]:
                    new_num = int(s[:i] + new_digit + s[i+1:])
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    # Standardize names for comparison
    scenario = scenario.upper()
    liar_names = {name.upper() for name in liar_count}
    days_lower = {day.lower() for day in days_of_week}

    # Guilty status mapping
    guilt_status = {name.upper(): (name.upper() == scenario) for name in statements}

    # Regex patterns
    pattern_is_guilty = re.compile(r'\b([A-Z]+)\s+is\s+guilty\b', re.IGNORECASE)
    pattern_is_not_guilty = re.compile(r'\b([A-Z]+)\s+is\s+not\s+guilty\b', re.IGNORECASE)
    pattern_i_am_guilty = re.compile(r'\bI\s+am\s+guilty\b', re.IGNORECASE)
    pattern_i_am_not_guilty = re.compile(r'\bI\s+am\s+not\s+guilty\b', re.IGNORECASE)

    for speaker, stmts in statements.items():
        speaker_upper = speaker.upper()

        for stmt in stmts:
            stmt_str = stmt.lower()

            # Skip statements that mention a day of the week
            if any(re.search(r'\b' + re.escape(day) + r'\b', stmt_str) for day in days_lower):
                continue

            subject = None
            claim_guilty = None

            # Check patterns
            m = pattern_i_am_not_guilty.search(stmt)
            if m:
                subject = speaker_upper
                claim_guilty = False
            else:
                m = pattern_i_am_guilty.search(stmt)
                if m:
                    subject = speaker_upper
                    claim_guilty = True
                else:
                    m = pattern_is_not_guilty.search(stmt)
                    if m:
                        subject = m.group(1).upper()
                        claim_guilty = False
                    else:
                        m = pattern_is_guilty.search(stmt)
                        if m:
                            subject = m.group(1).upper()
                            claim_guilty = True

            # If no recognizable statement, skip
            if subject is None or claim_guilty is None:
                continue

            # Determine truthfulness
            actual_guilt = guilt_status.get(subject, False)
            statement_truth = (claim_guilty == actual_guilt)

            # Validate against liar status
            if speaker_upper in liar_names:
                if statement_truth:
                    return False
            else:
                if not statement_truth:
                    return False

    return True

